def hours_to_amount(apps, schema_editor):
    """Old estimates were hours x rate: keep their value as the labour amount."""
    E = apps.get_model("claims", "RepairEstimate")
    for e in E.objects.all():
        e.labour_amount = (e.labour_hours or 0) * (e.labour_rate or 0)
        e.save(update_fields=["labour_amount"])


